(* [comment removed for export] *)
Definition art_drain_W5 (sp c GL GB : Z) : list (Z * Z) :=
  [(sp - 48, 48); (0x15c6f0 + 152, 16); (0x15c6f0 + 176, 16); (c, 32); ((if GL =? 0 then 0x15c6f0 + 168 else GB), 8)].

Lemma art_drain_mem_facts : forall (M : word -> option byte) (raw : word) (regs : bvmap 5 word) (sp c L F B bytes GL GB gbytes : Z),
  0x6b6000 + 48 <= sp -> sp < 2 ^ 64 -> 0 <= c -> c + 32 < 2 ^ 64 -> (c + 32 <= 0x10000 \/ 0x6b6000 <= c) -> apart (sp - 48) 48 c 32 ->
  (GL <> 0 -> 0x6b6000 <= GB /\ GB + 8 < 2 ^ 64 /\ apart (sp - 48) 48 GB 8 /\ apart c 32 GB 8 /\ wrA M GB 8) ->
  wrA M (sp - 48) 48 -> wrA M c 32 -> wrA M (0x15c6f0 + 152) 40 ->
  let M1 := art_drain_mem M sp raw regs c L F B bytes GL GB gbytes in
  mem_grows M M1 /\ art_agree (art_drain_W5 sp c GL GB) M M1
  /\ cellA M1 c 8 0 /\ cellA M1 (c + 8) 8 0 /\ cellA M1 (c + 16) 8 0 /\ cellA M1 (c + 24) 8 0
  /\ cellA M1 (0x15c6f0 + 160) 8 (GL + L) /\ cellA M1 (0x15c6f0 + 176) 8 B /\ cellA M1 (0x15c6f0 + 184) 8 (gbytes + bytes)
  /\ (GL = 0 -> cellA M1 (0x15c6f0 + 168) 8 F) /\ (GL <> 0 -> cellA M1 GB 8 F)
  /\ cellA M1 (sp - 8) 8 (U raw) /\ cellA M1 (sp - 16) 8 (U (getr regs 8)) /\ cellA M1 (sp - 24) 8 (U (getr regs 9)) /\ cellA M1 (sp - 32) 8 (U (getr regs 18))
  /\ cellA M1 (sp - 40) 8 (U (getr regs 19)) /\ cellA M1 (0x15c6f0 + 152) 4 0.
